jsonb\\"\r\n)","ALTER TABLE \\"public\\".\\"albums\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"photos\\" (\r\n    \\"id\\" \\"uuid\\" DEFAULT \\"extensions\\".\\"uuid_generate_v4\\"() NOT NULL,\r\n    \\"filename\\" \\"text\\" NOT NULL,\r\n    \\"original_name\\" \\"text\\" NOT NULL,\r\n    \\"storage_path\\" \\"text\\" NOT NULL,\r\n    \\"url\\" \\"text\\" NOT NULL,\r\n    \\"width\\" integer,\r\n    \\"height\\" integer,\r\n    \\"capture_date\\" timestamp with time zone,\r\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\r\n    \\"album_id\\" \\"uuid\\",\r\n    \\"user_id\\" \\"uuid\\"\r\n)","ALTER TABLE \\"public\\".\\"photos\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"profiles\\" (\r\n    \\"id\\" \\"uuid\\" NOT NULL,\r\n    \\"email\\" \\"text\\",\r\n    \\"full_name\\" \\"text\\",\r\n    \\"avatar_url\\" \\"text\\",\r\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\r\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"()\r\n)","ALTER TABLE \\"public\\".\\"profiles\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"templates\\" (\r\n    \\"id\\" \\"text\\" NOT NULL,\r\n    \\"name\\" \\"text\\" NOT NULL,\r\n    \\"type\\" \\"text\\" NOT NULL,\r\n    \\"category\\" \\"text\\",\r\n    \\"photo_count\\" integer NOT NULL,\r\n    \\"grid\\" \\"jsonb\\",\r\n    \\"regions\\" \\"jsonb\\",\r\n    \\"created_by\\" \\"text\\" DEFAULT 'system'::\\"text\\",\r\n    \\"is_system\\" boolean DEFAULT true,\r\n    \\"is_active\\" boolean DEFAULT true,\r\n    \\"sort_order\\" integer DEFAULT 0,\r\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\r\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\r\n    CONSTRAINT \\"templates_type_check\\" CHECK ((\\"type\\" = ANY (ARRAY['grid'::\\"text\\", 'advanced'::\\"text\\", 'cover'::\\"text\\"])))\r\n)","ALTER TABLE \\"public\\".\\"templates\\" OWNER TO \\"postgres\\"","COMMEN