ERENCES \\"auth\\".\\"users\\"(\\"id\\") ON DELETE CASCADE","ALTER TABLE ONLY \\"public\\".\\"user_settings\\"\r\n    ADD CONSTRAINT \\"user_settings_user_id_fkey\\" FOREIGN KEY (\\"user_id\\") REFERENCES \\"auth\\".\\"users\\"(\\"id\\") ON DELETE CASCADE","CREATE POLICY \\"Anyone can insert photos\\" ON \\"public\\".\\"photos\\" FOR INSERT WITH CHECK (true)","CREATE POLICY \\"Anyone can read active templates\\" ON \\"public\\".\\"templates\\" FOR SELECT USING ((\\"is_active\\" = true))","CREATE POLICY \\"Public photos access\\" ON \\"public\\".\\"photos\\" FOR SELECT USING (true)","CREATE POLICY \\"Service role can modify templates\\" ON \\"public\\".\\"templates\\" USING (true) WITH CHECK (true)","CREATE POLICY \\"Users can delete own albums\\" ON \\"public\\".\\"albums\\" FOR DELETE USING ((\\"auth\\".\\"uid\\"() = \\"user_id\\"))","CREATE POLICY \\"Users can delete own photos\\" ON \\"public\\".\\"photos\\" FOR DELETE USING ((\\"auth\\".\\"uid\\"() = \\"user_id\\"))","CREATE POLICY \\"Users can delete their own settings\\" ON \\"public\\".\\"user_settings\\" FOR DELETE USING ((\\"auth\\".\\"uid\\"() = \\"user_id\\"))","CREATE POLICY \\"Users can insert own albums\\" ON \\"public\\".\\"albums\\" FOR INSERT WITH CHECK ((\\"auth\\".\\"uid\\"() = \\"user_id\\"))","CREATE POLICY \\"Users can insert own photos\\" ON \\"public\\".\\"photos\\" FOR INSERT WITH CHECK ((\\"auth\\".\\"uid\\"() = \\"user_id\\"))","CREATE POLICY \\"Users can insert their own settings\\" ON \\"public\\".\\"user_settings\\" FOR INSERT WITH CHECK ((\\"auth\\".\\"uid\\"() = \\"user_id\\"))","CREATE POLICY \\"Users can update own albums\\" ON \\"public\\".\\"albums\\" FOR UPDATE USING ((\\"auth\\".\\"uid\\"() = \\"user_id\\"))","CREATE POLICY \\"Users can update own profile\\" ON \\"public\\".\\"profiles\\" FOR UPDATE USING ((\\"auth\\".\\"uid\\"() = \\"id\\"))","CREATE POLICY \\"Users can update their own settings\\" ON \\"public\\".\\"user_settings\\" FOR UPDATE USING ((\\"auth\\".\\"uid\\"() = 