 ON TABLE \\"public\\".\\"profiles\\" TO \\"service_role\\"","GRANT ALL ON TABLE \\"public\\".\\"templates\\" TO \\"anon\\"","GRANT ALL ON TABLE \\"public\\".\\"templates\\" TO \\"authenticated\\"","GRANT ALL ON TABLE \\"public\\".\\"templates\\" TO \\"service_role\\"","GRANT ALL ON TABLE \\"public\\".\\"user_settings\\" TO \\"anon\\"","GRANT ALL ON TABLE \\"public\\".\\"user_settings\\" TO \\"authenticated\\"","GRANT ALL ON TABLE \\"public\\".\\"user_settings\\" TO \\"service_role\\"","ALTER DEFAULT PRIVILEGES FOR ROLE \\"postgres\\" IN SCHEMA \\"public\\" GRANT ALL ON SEQUENCES TO \\"postgres\\"","ALTER DEFAULT PRIVILEGES FOR ROLE \\"postgres\\" IN SCHEMA \\"public\\" GRANT ALL ON SEQUENCES TO \\"anon\\"","ALTER DEFAULT PRIVILEGES FOR ROLE \\"postgres\\" IN SCHEMA \\"public\\" GRANT ALL ON SEQUENCES TO \\"authenticated\\"","ALTER DEFAULT PRIVILEGES FOR ROLE \\"postgres\\" IN SCHEMA \\"public\\" GRANT ALL ON SEQUENCES TO \\"service_role\\"","ALTER DEFAULT PRIVILEGES FOR ROLE \\"postgres\\" IN SCHEMA \\"public\\" GRANT ALL ON FUNCTIONS TO \\"postgres\\"","ALTER DEFAULT PRIVILEGES FOR ROLE \\"postgres\\" IN SCHEMA \\"public\\" GRANT ALL ON FUNCTIONS TO \\"anon\\"","ALTER DEFAULT PRIVILEGES FOR ROLE \\"postgres\\" IN SCHEMA \\"public\\" GRANT ALL ON FUNCTIONS TO \\"authenticated\\"","ALTER DEFAULT PRIVILEGES FOR ROLE \\"postgres\\" IN SCHEMA \\"public\\" GRANT ALL ON FUNCTIONS TO \\"service_role\\"","ALTER DEFAULT PRIVILEGES FOR ROLE \\"postgres\\" IN SCHEMA \\"public\\" GRANT ALL ON TABLES TO \\"postgres\\"","ALTER DEFAULT PRIVILEGES FOR ROLE \\"postgres\\" IN SCHEMA \\"public\\" GRANT ALL ON TABLES TO \\"anon\\"","ALTER DEFAULT PRIVILEGES FOR ROLE \\"postgres\\" IN SCHEMA \\"public\\" GRANT ALL ON TABLES TO \\"authenticated\\"","ALTER DEFAULT PRIVILEGES FOR ROLE \\"postgres\\" IN SCHEMA \\"public\\" GRANT ALL ON TABLES TO \\"service_role\\""}	remote_schema
20240122	{"-- Ensure the 'photos' bucket exists\r\n-- Ensure the 'photos' bucket exists (Commented out for Seed compatibility)\r\n-- INSERT INTO storage.buckets (id, name, public)\r\n-- VALUES ('photos', 'photos', true)\r\n-- ON CONFLICT (id) DO NOTHING;\r\n\r\n-- Policy: Allow authenticated users to upload (INSERT) to 'photos' bucket\r\n-- Note: We check that the folder path starts with their user ID to prevent overwriting others' files\r\n-- Assuming path structure: user_id/filename\r\nCREATE POLICY \\"Allow Authenticated Uploads\\"\r\nON storage.objects FOR INSERT\r\nTO authenticated\r\nWITH CHECK (\r\n  bucket_id = 'photos' AND\r\n  (storage.foldername(name))[1] = auth.uid()::text\r\n)","-- Policy: Allow public to view (SELECT) files in 'photos' bucket\r\nCREATE POLICY \\"Allow Public Access\\"\r\nON storage.objects FOR SELECT\r\nTO public\r\nUSING ( bucket_id = 'photos' )","-- Policy: Allow users to UPDATE their own files\r\nCREATE POLICY \\"Allow User Update\\"\r\nON storage.objects FOR UPDATE\r\nTO authenticated\r\nUSING ( bucket_id = 'photos' AND owner = auth.uid() )\r\nWITH CHECK ( bucket_id = 'photos' AND owner = auth.uid() )","-- Policy: Allow users to DELETE their own files\r\nCREATE POLICY \\"Allow User Delete\\"\r\nON storage.objects FOR DELETE\r\nTO authenticated\r\nUSING ( bucket_id = 'photos' AND owner = auth.uid() )"}	storage_policies
20260123	{"-- Add role column to profiles table for admin functionality\r\nALTER TABLE public.profiles \r\nADD COLUMN IF NOT EXISTS role text NOT NULL DEFAULT 'user' \r\nCHECK (role IN ('user', 'admin'))","-- Create index for role lookups\r\nCREATE INDEX IF NOT EXISTS idx_profiles_role ON public.profiles(role)","-- Set existing users as admin (for development)\r\nUPDATE public.profiles SET role = 'admin' WHERE role = 'user'"}	add_role_to_profiles
20260124	{"-- Create a function to handle role updates\r\nCREATE OR REPLACE FUNCTION public.handle_role_update() \r\nRETURNS TRIGGER AS $$\r\nBEGIN\r\n  -- Update the auth.users table with the new role in app_metadata\r\n  UPDATE auth.users\r\n  SET raw_app_meta_data = \r\n    jsonb_set(\r\n      COALESCE(raw_app_meta_data, '{}'::jsonb),\r\n      '{role}',\r\n      to_jsonb(NEW.role)\r\n    )\r\n  WHERE id = NEW.id;\r\n  \r\n  RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql SECURITY DEFINER","-- Create the trigger\r\nDROP TRIGGER IF EXISTS on_role_change ON public.profiles","CREATE TRIGGER on_role_change\r\n  AFTER INSERT OR UPDATE OF role ON public.profiles\r\n  FOR EACH ROW\r\n  EXECUTE FUNCTION public.handle_role_update()","-- One-time backfill for existing users\r\n-- This ensures current admins get the metadata set immediately\r\nDO $$\r\nDECLARE\r\n  user_record RECORD;\r\nBEGIN\r\n  FOR user_record IN SELECT id, role FROM public.profiles LOOP\r\n    UPDATE auth.users\r\n    SET raw_app_meta_data = \r\n      jsonb_set(\r\n        COALESCE(raw_app_meta_data, '{}'::jsonb),\r\n        '{role}',\r\n        to_jsonb(user_record.role)\r\n      )\r\n    WHERE id = user_record.id;\r\n  END LOOP;\r\nEND;\r\n$$"}	sync_role_to_metadata
20260125120000	{"-- Re-create Types Table with ID\r\ndrop table if exists template_types cascade","create table template_types (\r\n  id serial primary key,\r\n  code text unique not null,\r\n  description text\r\n)","-- Re-create Categories Table with ID\r\ndrop table if exists template_categories cascade","create table template_categories (\r\n  id serial primary key,\r\n  code text unique not null,\r\n  label text\r\n)","-- Update Templates Table\r\n-- Drop old code columns if they exist\r\nalter table templates drop column if exists type_code","alter table templates drop column if exists category_code","-- Add new ID columns\r\nalter table templates add column type_id integer references template_types(id)","alter table templates add column category_id integer references template_categories(id)","-- Optional: Create index for performance\r\ncreate index if not exists idx_templates_type_id on templates(type_id)","create index if not exists idx_templates_category_id on templates(category_id)"}	use_integer_ids
20260125130000	{"-- Drop legacy text columns\r\nalter table templates drop column if exists type","alter table templates drop column if exists category","-- Drop code columns if they still exist (previously attempted)\r\nalter table templates drop column if exists type_code","alter table templates drop column if exists category_code"}	drop_legacy_columns
20260125140000	{"-- Add missing trigger to create profile when auth.users is inserted\r\ndrop trigger if exists on_auth_user_created on auth.users","create trigger on_auth_user_created\r\n  after insert on auth.users\r\n  for each row execute procedure public.handle_new_user()"}	create_profile_trigger
20260125150000	{"-- Create User Roles Table\r\ncreate table if not exists user_roles (\r\n  id serial primary key,\r\n  code text unique not null,\r\n  description text\r\n)","-- Seed Initial Roles\r\n-- Seed Initial Roles (Commented out to allow seed.sql to handle this without conflict)\r\n-- insert into user_roles (id, code, description) values\r\n--   (1, 'ADMIN', 'Administrator with full access'),\r\n--   (2, 'USER', 'Standard user'),\r\n--   (3, 'GUEST', 'Guest user with limited access')\r\n-- on conflict (id) do update set code = excluded.code;\r\n\r\n-- Update Profiles with Role FK\r\nalter table profiles add column if not exists role_id integer references user_roles(id) default 2","-- Create index for performance\r\ncreate index if not exists idx_profiles_role_id on profiles(role_id)"}	add_roles
20260125160000	{"-- 1. Drop dependencies of the legacy 'role' column\r\ndrop trigger if exists on_role_change on public.profiles","drop function if exists public.handle_role_update()","-- 2. Drop the legacy text column\r\nalter table public.profiles drop column if exists role","-- 3. Re-create the sync function to work with 'role_id' and 'user_roles'\r\ncreate or replace function public.handle_role_update() \r\nreturns trigger as $$\r\ndeclare\r\n  role_code text;\r\nbegin\r\n  -- Lookup the text code (ADMIN, USER, GUEST) from the FK\r\n  select code into role_code from public.user_roles where id = new.role_id;\r\n\r\n  -- Default to USER if something breaks\r\n  if role_code is null then\r\n    role_code := 'USER';\r\n  end if;\r\n\r\n  -- Update auth.users metadata\r\n  update auth.users\r\n  set raw_app_meta_data = \r\n    jsonb_set(\r\n      coalesce(raw_app_meta_data, '{}'::jsonb),\r\n      '{role}',\r\n      to_jsonb(role_code)\r\n    )\r\n  where id = new.id;\r\n  \r\n  return new;\r\nend;\r\n$$ language plpgsql security definer","-- 4. Re-attach trigger to 'role_id'\r\ncreate trigger on_role_change\r\n  after insert or update of role_id on public.profiles\r\n  for each row\r\n  execute function public.handle_role_update()"}	drop_legacy_role_column
20260208100000	{"-- Add support for storing full SVG content in canva_frames\r\n-- This allows two storage modes:\r\n-- 1. Simple frames: path + view_box columns\r\n-- 2. Complex SVG: svg_content column with full SVG markup\r\n\r\nALTER TABLE public.canva_frames\r\nADD COLUMN IF NOT EXISTS frame_type TEXT DEFAULT 'simple' CHECK (frame_type IN ('simple', 'complex')),\r\nADD COLUMN IF NOT EXISTS svg_content TEXT","-- Add comment to explain usage\r\nCOMMENT ON COLUMN public.canva_frames.frame_type IS 'simple = uses path+view_box, complex = uses svg_content'","COMMENT ON COLUMN public.canva_frames.svg_content IS 'Full SVG content for complex frames (used when frame_type=complex)'"}	add_svg_content_to_canva_frames
20260129000000	{"-- Create a function to allow admins to update user roles\r\n-- This function must be SECURITY DEFINER to bypass RLS and access auth.users\r\nCREATE OR REPLACE FUNCTION public.update_user_role(target_user_id UUID, new_role_id INT)\r\nRETURNS JSONB\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public\r\nAS $$\r\nDECLARE\r\n  current_user_role INT;\r\n  new_role_code TEXT;\r\n  result JSONB;\r\nBEGIN\r\n  -- 1. Check if the executing user is an ADMIN\r\n  SELECT role_id INTO current_user_role\r\n  FROM public.profiles\r\n  WHERE id = auth.uid();\r\n\r\n  IF current_user_role != 1 THEN\r\n    RAISE EXCEPTION 'Access Denied: Only Admins can update roles.';\r\n  END IF;\r\n\r\n  -- 2. Validate the new role_id exists and get its code\r\n  SELECT code INTO new_role_code\r\n  FROM public.user_roles\r\n  WHERE id = new_role_id;\r\n\r\n  IF new_role_code IS NULL THEN\r\n    RAISE EXCEPTION 'Invalid Role ID';\r\n  END IF;\r\n\r\n  -- 3. Update public.profiles\r\n  UPDATE public.profiles\r\n  SET role_id = new_role_id,\r\n      updated_at = NOW()\r\n  WHERE id = target_user_id;\r\n\r\n  -- 4. Update auth.users metadata (to keep them in sync)\r\n  -- We use the supabase-specific feature to update user metadata via SQL if possible?\r\n  -- Actually, standard SQL update on auth.users works if we have permissions (SECURITY DEFINER gives us that).\r\n  -- We need to construct the new raw_app_meta_data.\r\n  UPDATE auth.users\r\n  SET raw_app_meta_data = \r\n    COALESCE(raw_app_meta_data, '{}'::jsonb) || \r\n    jsonb_build_object('role', new_role_code)\r\n  WHERE id = target_user_id;\r\n\r\n  -- 5. Return success\r\n  RETURN jsonb_build_object(\r\n    'success', true,\r\n    'user_id', target_user_id,\r\n    'new_role', new_role_code\r\n  );\r\nEXCEPTION\r\n  WHEN OTHERS THEN\r\n    RETURN jsonb_build_object(\r\n      'success', false,\r\n      'error', SQLERRM\r\n    );\r\nEND;\r\n$$","-- Grant execute permission to authenticated users (logic inside handles auth checks)\r\nGRANT EXECUTE ON FUNCTION public.update_user_role(UUID, INT) TO authenticated"}	admin_update_role_function
20260129000001	{"-- Allow Admins to see all profiles\r\n-- Current policies only allow viewing own profile.\r\n\r\n-- Drop existing overlapping policy if it exists (though \\"Users can view own profile\\" is fine to keep, we just add a broader one)\r\n-- Actually, let's create a new policy \\"Admins can view all profiles\\".\r\n\r\nCREATE POLICY \\"Admins can view all profiles\\"\r\nON public.profiles\r\nFOR SELECT\r\nTO authenticated\r\nUSING (\r\n  EXISTS (\r\n    SELECT 1 FROM public.profiles\r\n    WHERE profiles.id = auth.uid() AND profiles.role_id = 1\r\n  )\r\n)"}	admin_view_all_profiles
20260129000002	{"-- Fix RLS Recursion by using JWT claims instead of querying the table\r\n-- Previous policy \\"Admins can view all profiles\\" caused infinite recursion.\r\n\r\nDROP POLICY IF EXISTS \\"Admins can view all profiles\\" ON public.profiles","CREATE POLICY \\"Admins can view all profiles\\"\r\nON public.profiles\r\nFOR SELECT\r\nTO authenticated\r\nUSING (\r\n  (auth.jwt() -> 'app_metadata' ->> 'role')::text = 'ADMIN'\r\n  OR\r\n  auth.uid() = id\r\n)"}	fix_rls_recursion
20260207132126	{"create sequence \\"public\\".\\"template_classifications_id_seq\\"","drop index if exists \\"public\\".\\"idx_templates_type_id\\"","alter table if exists \\"public\\".\\"templates\\" drop constraint if exists \\"templates_pkey\\"","drop index if exists \\"public\\".\\"templates_pkey\\"","create table \\"public\\".\\"template_classifications\\" (\r\n    \\"id\\" integer not null default nextval('public.template_classifications_id_seq'::regclass),\r\n    \\"code\\" text not null,\r\n    \\"label\\" text\r\n      )","alter table \\"public\\".\\"templates\\" add column \\"classification_type_id\\" integer","alter table \\"public\\".\\"templates\\" add column \\"description\\" text","alter table \\"public\\".\\"templates\\" alter column \\"created_by\\" drop default","alter table \\"public\\".\\"templates\\" alter column \\"created_by\\" set data type uuid using \\"created_by\\"::uuid","alter table \\"public\\".\\"templates\\" alter column \\"id\\" set data type integer using \\"id\\"::integer","alter sequence \\"public\\".\\"template_classifications_id_seq\\" owned by \\"public\\".\\"template_classifications\\".\\"id\\"","CREATE INDEX idx_templates_classification_type_id ON public.templates USING btree (classification_type_id)","CREATE UNIQUE INDEX template_classifications_code_key ON public.template_classifications USING btree (code)","CREATE UNIQUE INDEX template_classifications_pkey ON public.template_classifications USING btree (id)","CREATE UNIQUE INDEX templates_pkey ON public.templates USING btree (id)","alter table \\"public\\".\\"template_classifications\\" add constraint \\"template_classifications_pkey\\" PRIMARY KEY using index \\"template_classifications_pkey\\"","alter table \\"public\\".\\"template_classifications\\" add constraint \\"template_classifications_code_key\\" UNIQUE using index \\"template_classifications_code_key\\"","alter table \\"public\\".\\"templates\\" add constraint \\"templates_classification_type_id_fkey\\" FOREIGN KEY (classification_type_id) REFERENCES public.template_classifications(id) not valid","alter table \\"public\\".\\"templates\\" validate constraint \\"templates_classification_type_id_fkey\\"","alter table \\"public\\".\\"templates\\" add constraint \\"templates_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES public.profiles(id) not valid","alter table \\"public\\".\\"templates\\" validate constraint \\"templates_created_by_fkey\\"","set check_function_bodies = off","CREATE OR REPLACE FUNCTION public.handle_role_update()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\nAS $function$\r\ndeclare\r\n  role_code text;\r\nbegin\r\n  select code into role_code from public.user_roles where id = new.role_id;\r\n  \r\n  if role_code is null then\r\n    role_code := 'USER';\r\n  end if;\r\n  \r\n  update auth.users\r\n  set raw_app_meta_data = \r\n    jsonb_set(\r\n      coalesce(raw_app_meta_data, '{}'::jsonb),\r\n      '{role}',\r\n      to_jsonb(role_code)\r\n    )\r\n  where id = new.id;\r\n  \r\n  return new;\r\nend;\r\n$function$","CREATE OR REPLACE FUNCTION public.update_user_role(target_user_id uuid, new_role_id integer)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public'\r\nAS $function$\r\nDECLARE\r\n  current_user_role INT;\r\n  new_role_code TEXT;\r\n  result JSONB;\r\nBEGIN\r\n  SELECT role_id INTO current_user_role\r\n  FROM public.profiles\r\n  WHERE id = auth.uid();\r\n\r\n  IF current_user_role != 1 THEN\r\n    RAISE EXCEPTION 'Access Denied: Only Admins can update roles.';\r\n  END IF;\r\n\r\n  SELECT code INTO new_role_code\r\n  FROM public.user_roles\r\n  WHERE id = new_role_id;\r\n\r\n  IF new_role_code IS NULL THEN\r\n    RAISE EXCEPTION 'Invalid Role ID';\r\n  END IF;\r\n\r\n  UPDATE public.profiles\r\n  SET role_id = new_role_id,\r\n      updated_at = NOW()\r\n  WHERE id = target_user_id;\r\n\r\n  UPDATE auth.users\r\n  SET raw_app_meta_data = \r\n    COALESCE(raw_app_meta_data, '{}'::jsonb) || \r\n    jsonb_build_object('role', new_role_code)\r\n  WHERE id = target_user_id;\r\n\r\n  RETURN jsonb_build_object(\r\n    'success', true,\r\n    'user_id', target_user_id,\r\n    'new_role', new_role_code\r\n  );\r\nEXCEPTION\r\n  WHEN OTHERS THEN\r\n    RETURN jsonb_build_object(\r\n      'success', false,\r\n      'error', SQLERRM\r\n    );\r\nEND;\r\n$function$","grant delete on table \\"public\\".\\"template_classifications\\" to \\"anon\\"","grant insert on table \\"public\\".\\"template_classifications\\" to \\"anon\\"","grant references on table \\"public\\".\\"template_classifications\\" to \\"anon\\"","grant select on table \\"public\\".\\"template_classifications\\" to \\"anon\\"","grant trigger on table \\"public\\".\\"template_classifications\\" to \\"anon\\"","grant truncate on table \\"public\\".\\"template_classifications\\" to \\"anon\\"","grant update on table \\"public\\".\\"template_classifications\\" to \\"anon\\"","grant delete on table \\"public\\".\\"template_classifications\\" to \\"authenticated\\"","grant insert on table \\"public\\".\\"template_classifications\\" to \\"authenticated\\"","grant references on table \\"public\\".\\"template_classifications\\" to \\"authenticated\\"","grant select on table \\"public\\".\\"template_classifications\\" to \\"authenticated\\"","grant trigger on table \\"public\\".\\"template_classifications\\" to \\"authenticated\\"","grant truncate on table \\"public\\".\\"template_classifications\\" to \\"authenticated\\"","grant update on table \\"public\\".\\"template_classifications\\" to \\"authenticated\\"","grant delete on table \\"public\\".\\"template_classifications\\" to \\"service_role\\"","grant insert on table \\"public\\".\\"template_classifications\\" to \\"service_role\\"","grant references on table \\"public\\".\\"template_classifications\\" to \\"service_role\\"","grant select on table \\"public\\".\\"template_classifications\\" to \\"service_role\\"","grant trigger on table \\"public\\".\\"template_classifications\\" to \\"service_role\\"","grant truncate on table \\"public\\".\\"template_classifications\\" to \\"service_role\\"","grant update on table \\"public\\".\\"template_classifications\\" to \\"service_role\\""}	remote_schema
20260207150000	{"-- Create canva_frames table for storing SVG frame shapes\r\n-- This is a NEW table, does not modify any existing tables\r\n\r\nCREATE TABLE IF NOT EXISTS public.canva_frames (\r\n    id UUID DEFAULT extensions.uuid_generate_v4() PRIMARY KEY,\r\n    name TEXT NOT NULL,\r\n    path TEXT NOT NULL,                    -- SVG path data (d attribute)\r\n    view_box TEXT NOT NULL DEFAULT '0 0 100 100',  -- SVG viewBox attribute\r\n    category TEXT DEFAULT 'general',       -- Category for organization (hearts, clouds, stars, etc.)\r\n    is_public BOOLEAN DEFAULT true,        -- Whether frame is publicly available\r\n    created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,\r\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\r\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now()\r\n)","-- Add RLS policies\r\nALTER TABLE public.canva_frames ENABLE ROW LEVEL SECURITY","-- Everyone can view public frames (even unauthenticated)\r\nCREATE POLICY \\"Public frames are viewable by everyone\\"\r\n    ON public.canva_frames\r\n    FOR SELECT\r\n    USING (is_public = true)","-- Authenticated users can view all frames\r\nCREATE POLICY \\"Authenticated users can view frames\\"\r\n    ON public.canva_frames\r\n    FOR SELECT\r\n    TO authenticated\r\n    USING (true)","-- Admins can manage frames (insert, update, delete) - role_id = 1 is ADMIN\r\nCREATE POLICY \\"Admins can manage frames\\"\r\n    ON public.canva_frames\r\n    FOR ALL\r\n    TO authenticated\r\n    USING (\r\n        EXISTS (\r\n            SELECT 1 FROM public.profiles \r\n            WHERE id = auth.uid() AND role_id = 1\r\n        )\r\n    )","-- Create index for faster lookups\r\nCREATE INDEX IF NOT EXISTS idx_canva_frames_category ON public.canva_frames(category)","CREATE INDEX IF NOT EXISTS idx_canva_frames_public ON public.canva_frames(is_public)","-- Add comment\r\nCOMMENT ON TABLE public.canva_frames IS 'Stores SVG frame shapes for the custom layout editor'"}	create_canva_frames_table
20260208000000	{"-- Add support for complex SVG frames with full SVG content\r\n-- This migration only ADDS columns, does not modify or delete anything\r\n\r\n-- Add frame_type column to distinguish simple (path-only) from complex (full SVG) frames\r\nALTER TABLE public.canva_frames \r\nADD COLUMN IF NOT EXISTS frame_type TEXT NOT NULL DEFAULT 'simple'","-- Add svg_content column to store full SVG markup for complex frames\r\nALTER TABLE public.canva_frames \r\nADD COLUMN IF NOT EXISTS svg_content TEXT","-- Add constraint to validate frame_type values\r\nALTER TABLE public.canva_frames\r\nADD CONSTRAINT valid_frame_type CHECK (frame_type IN ('simple', 'complex'))","-- Add comment explaining the fields\r\nCOMMENT ON COLUMN public.canva_frames.frame_type IS 'Type of frame: simple (uses path+view_box) or complex (uses svg_content)'","COMMENT ON COLUMN public.canva_frames.svg_content IS 'Full SVG markup for complex frames with multiple paths, colors, gradients, etc.'","-- Create index for faster filtering by frame type\r\nCREATE INDEX IF NOT EXISTS idx_canva_frames_type ON public.canva_frames(frame_type)"}	add_svg_content_field
20260208110000	{"-- Seed canva_frames table with sample data from CANVA_TEMPLATES\r\n-- This inserts individual frame shapes, not full templates\r\n\r\n-- Simple frames (path + view_box only)\r\nINSERT INTO public.canva_frames (name, path, view_box, category, frame_type, is_public)\r\nVALUES\r\n-- Simple rectangular frame\r\n('Simple Rectangle', 'M 164.121094 20 L 699.878906 20 L 699.878906 844 L 164.121094 844 Z M 164.121094 20', '164.121094 20.0 535.7578120000001 824.0', 'basic', 'simple', true),\r\n\r\n-- Rounded rectangle\r\n('Rounded Rectangle', 'M 248.015625 100.269531 L 616 100.269531 L 616 764 L 248.015625 764 Z M 248.015625 100.269531', '248.015625 100.269531 367.984375 663.730469', 'basic', 'simple', true),\r\n\r\n-- Portrait frame\r\n('Portrait Frame', 'M 235.269531 29 L 629 29 L 629 834.617188 L 235.269531 834.617188 Z M 235.269531 29', '235.269531 29.0 393.73046899999997 805.617188', 'basic', 'simple', true),\r\n\r\n-- Landscape frame\r\n('Landscape Frame', 'M 191 36 L 673 36 L 673 827.738281 L 191 827.738281 Z M 191 36', '191.0 36.0 482.0 791.738281', 'basic', 'simple', true),\r\n\r\n-- Square frame\r\n('Square Frame', 'M 0.875 0.511719 L 610.625 0.511719 L 610.625 619.261719 L 0.875 619.261719 Z M 0.875 0.511719', '0.875 0.511719 609.75 618.75', 'basic', 'simple', true)","-- Complex decorative frames (would use svg_content in the future)\r\n-- For now, adding a few more interesting path shapes\r\nINSERT INTO public.canva_frames (name, path, view_box, category, frame_type, is_public)\r\nVALUES\r\n-- Artboard shape (notebook/paper look)\r\n('Paper Stack', 'M1171.44,721.41c13.34-.93,26.8-1.06,40-3,33-4.76,51.32-25.62,51.37-57.15,0-33.24-15.66-51.78-49.31-58.4-15.61-3.07-31.17-6.34-46.72-9.66-.75-.16-1.2-1.72-4.08-6.2,22.15-2.74,42.58-5.46,63.07-7.76,37.15-4.16,56.1-22.19,57.38-55,1.4-35.78-15.36-54.88-54.43-61.39-41-6.84-82.06-13.33-125.48-20.36', '231.76999999999998 261.38000000000005 1549.7200000000005 1479.48', 'decorative', 'simple', true),\r\n\r\n-- Organic blob shape\r\n('Blob Frame', 'M1678,1567.52l40.07-171.76c-93.31-25.11-187.73-38.06-281.87-57.75,115.8-22,232-39.47,347.53-71.07-20.22-90.11-40-178.18-60.42-269.22', '216.28000000000006 432.0099999999999 1567.4499999999998 1135.5100000000002', 'organic', 'simple', true),\r\n\r\n-- Peanut/organic shape\r\n('Organic Peanut', 'M1512.15,1009.41c-6.2,49.51,2.84,96.1,28.86,139.32q22.11,36.7,41.79,74.89a194,194,0,0,1,21.77,86.41c.7,38.07-9.63,72.6-33.57,102.69', '372.6700000000003 109.48 1254.58 1819.3300000000002', 'organic', 'simple', true)","-- Add index on category for faster filtering\r\nCREATE INDEX IF NOT EXISTS idx_canva_frames_category ON public.canva_frames(category)","CREATE INDEX IF NOT EXISTS idx_canva_frames_frame_type ON public.canva_frames(frame_type)"}	seed_canva_frames
