20260217170000	{"-- Rename misused templates.description column to a semantic name.\r\n-- This column stores template/editor configuration JSON payloads.\r\n\r\nDO $$\r\nBEGIN\r\n  IF EXISTS (\r\n    SELECT 1\r\n    FROM information_schema.columns\r\n    WHERE table_schema = 'public'\r\n      AND table_name = 'templates'\r\n      AND column_name = 'description'\r\n  ) AND NOT EXISTS (\r\n    SELECT 1\r\n    FROM information_schema.columns\r\n    WHERE table_schema = 'public'\r\n      AND table_name = 'templates'\r\n      AND column_name = 'template_config'\r\n  ) THEN\r\n    ALTER TABLE public.templates\r\n      RENAME COLUMN description TO template_config;\r\n  END IF;\r\nEND $$"}	rename_templates_description_to_template_config
20260217223000	{"-- Ensure avatars bucket exists and is publicly readable.\r\ninsert into storage.buckets (id, name, public)\r\nvalues ('avatars', 'avatars', true)\r\non conflict (id) do update\r\nset\r\n  name = excluded.name,\r\n  public = excluded.public","-- Replace any legacy avatar policies with explicit, idempotent ones.\r\ndrop policy if exists \\"Authenticated Insert\\" on storage.objects","drop policy if exists \\"Authenticated Update\\" on storage.objects","drop policy if exists \\"Authenticated Delete\\" on storage.objects","drop policy if exists \\"Public Access\\" on storage.objects","drop policy if exists \\"Avatars: Insert own\\" on storage.objects","drop policy if exists \\"Avatars: Update own\\" on storage.objects","drop policy if exists \\"Avatars: Delete own\\" on storage.objects","drop policy if exists \\"Avatars: Public read\\" on storage.objects","create policy \\"Avatars: Insert own\\"\r\non storage.objects\r\nfor insert\r\nto authenticated\r\nwith check (\r\n  bucket_id = 'avatars'\r\n  and (storage.foldername(name))[1] = auth.uid()::text\r\n)","create policy \\"Avatars: Update own\\"\r\non storage.objects\r\nfor update\r\nto authenticated\r\nusing (\r\n  bucket_id = 'avatars'\r\n  and (storage.foldername(name))[1] = auth.uid()::text\r\n)\r\nwith check (\r\n  bucket_id = 'avatars'\r\n  and (storage.foldername(name))[1] = auth.uid()::text\r\n)","create policy \\"Avatars: Delete own\\"\r\non storage.objects\r\nfor delete\r\nto authenticated\r\nusing (\r\n  bucket_id = 'avatars'\r\n  and (storage.foldername(name))[1] = auth.uid()::text\r\n)","create policy \\"Avatars: Public read\\"\r\non storage.objects\r\nfor select\r\nto public\r\nusing (\r\n  bucket_id = 'avatars'\r\n)"}	add_avatars_storage_policies
